parameters.jsCode:
if ($json.errors?.length) {
  throw new Error(
    'Neo4j-fejl: ' +
    $json.errors.map(error => error.message).join('; ')
  );
}

const data = $json.data;

if (!Array.isArray(data?.fields) || !Array.isArray(data?.values)) {
  throw new Error('Neo4j returnerede et uventet format.');
}

const input = $('When Executed by Another Workflow').item.json;

const sources = data.values.map((row, index) => {
  const source = Object.fromEntries(
    data.fields.map((field, fieldIndex) => [
      field,
      row[fieldIndex]
    ])
  );

  return {
    source_number: index + 1,
    ...source
  };
});

return {
  json: {
    country: input.country,
    question: input.question,
    found: sources.length > 0,
    source_count: sources.length,
    sources,
    message: sources.length > 0
      ? 'Søgningen har fundet tekstbidder. De er ikke nødvendigvis alle relevante. Brug kun oplysninger, der besvarer spørgsmålet og gælder det valgte land. Henvis med [Kilde N] ud fra source_number og medtag den tilhørende source_url. Hvis teksterne ikke besvarer spørgsmålet, sig det tydeligt. retrieved_at er indsamlingsdatoen, ikke kildens opdateringsdato.'
      : 'Der blev ikke fundet kildetekster for denne søgning og dette land i databasen. Besvar ikke spørgsmålet ud fra kilder om andre lande.'
  }
};
